WITH filtered AS (SELECT *, IF(is_flagged, 'Yes', 'No') AS is_flagged_label, COALESCE(merchant, 'N/A') AS merchant_filled FROM transactions WHERE merchant IS DISTINCT FROM 'Lazada') SELECT id, txn_type, amount, txn_time, merchant, is_flagged FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY txn_type, merchant ORDER BY amount DESC NULLS LAST, id) AS row_num FROM filtered) x WHERE row_num = 1;
